<template><view class="page"><view class="logo">随</view><text class="title">随行录</text><text class="sub">记录想法，推进每件重要的事</text><view class="tabs"><text :class="{on:mode==='login'}" @tap="mode='login'">登录</text><text :class="{on:mode==='register'}" @tap="mode='register'">注册</text></view><input v-model="email" placeholder="电子邮箱"/><input v-model="password" password placeholder="至少 6 位密码"/><input v-if="mode==='register'" v-model="nickname" placeholder="昵称"/><button @tap="submit">{{mode==='login'?'登录':'注册并登录'}}</button></view></template><script setup>import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{configured,supabase}from'../../lib/supabase';const mode=ref('login'),email=ref(''),password=ref(''),nickname=ref('');onShow(async()=>{if(configured&&(await supabase.auth.getSession()).data.session)uni.switchTab({url:'/pages/home/home'})});async function submit(){if(!configured)return uni.showModal({title:'需要配置 Supabase',content:'请在 uniapp/.env 中填写项目 URL 和匿名密钥',showCancel:false});try{if(mode.value==='register'){const{error}=await supabase.auth.signUp({email:email.value,password:password.value,options:{data:{nickname:nickname.value}}});if(error)throw error}else{const{error}=await supabase.auth.signInWithPassword({email:email.value,password:password.value});if(error)throw error}uni.switchTab({url:'/pages/home/home'})}catch(e){uni.showToast({title:e.message,icon:'none'})}}</script><style scoped>.page{padding:90px 28px}.logo{width:68px;height:68px;border-radius:22px;background:#70c3f1;color:#fff;display:flex;align-items:center;justify-content:center;font-size:30px;font-weight:700}.title{display:block;font-size:30px;font-weight:700;margin:20px 0 6px}.sub{color:#7895a7}.tabs{display:flex;background:#e5f3fb;border-radius:14px;margin:34px 0 20px;padding:4px}.tabs text{flex:1;text-align:center;padding:10px}.tabs .on{background:#fff;border-radius:10px;color:#2680ad}input{background:#fff;border:1px solid #d7e8f2;border-radius:13px;padding:14px;margin-bottom:14px}button{background:#70c3f1;color:#fff;border-radius:14px;margin-top:12px}</style>
